script:
type_of_examination = frappe.form_dict.get("type_of_examination")

if type_of_examination == "Random Test":
    result = frappe.db.sql(""" SELECT parameter_type, measure_name, measure_code, uom FROM `tabMedical Parameters` WHERE parameter_type = 'Random Check' """, as_dict = 1)
else:
    result = frappe.db.sql(""" SELECT parameter_type, measure_name, measure_code, uom FROM `tabMedical Parameters`  WHERE parameter_type != 'Random Check' """, as_dict = 1)

frappe.response["message"] = result
